`timescale 1ns/1ns
module top;
bit done;
task automatic run(input int value);
 fork int saved=value; begin #1;saved+=2;end begin #2;$display("%0d",saved);end join
endtask
initial begin run(7); done=1; end
initial begin #20; if(!done)begin $display("watchdog");$finish(0);end end
endmodule

