`timescale 1ns/1ns
module top;
bit done;
task automatic run();
 logic[128:0] value='x;
 fork
  begin #1;value='z;#1;value='1;end
  begin @(value);$display("any %0t %0d",$time,value === 'z);@(posedge value[64]);$display("edge %0t %0d",$time,value === '1);end
 join
endtask
initial begin run(); done=1; end
initial begin #20; if(!done)begin $display("watchdog");$finish(0);end end
endmodule

